OPS = [{'file': 'app/src/main/java/com/saney/ytmimporter/MainActivity.kt', 'old': '                    onHistoryState = { job, historyStatus ->\n                        syncHistoryFromJob(\n                            job,\n                            historyStatus\n                        )\n                    },\n', 'new': '                    onHistoryState = { job, historyStatus ->\n                        syncHistoryFromJob(\n                            job = job,\n                            historyStatus = historyStatus,\n                            stateSourceTracks = tracks\n                        )\n                    },\n', 'name': 'Pass authoritative write tracks into History sync'}, {'file': 'app/src/main/java/com/saney/ytmimporter/MainActivity.kt', 'old': '    private fun syncHistoryFromJob(\n        job: PendingJob,\n        historyStatus: HistoryStatus\n    ) {\n', 'new': '    private fun syncHistoryFromJob(\n        job: PendingJob,\n        historyStatus: HistoryStatus,\n        stateSourceTracks: List<Track>\n    ) {\n', 'name': 'Add History state-source parameter'}, {'file': 'app/src/main/java/com/saney/ytmimporter/MainActivity.kt', 'old': '                    .sortedBy { it.index }\n                    .toMutableList()\n            }\n\n        val now = System.currentTimeMillis()\n', 'new': '                    .sortedBy { it.index }\n                    .toMutableList()\n            }\n\n        stateSourceTracks.forEachIndexed {\n                fallbackIndex,\n                track ->\n\n            val authoritative =\n                historyTrackFromTrack(\n                    track = track,\n                    fallbackIndex = fallbackIndex\n                )\n\n            val targetIndex =\n                track.historyIndex\n                    ?.let { historyIndex ->\n                        merged.indexOfFirst {\n                            it.index == historyIndex\n                        }\n                    }\n                    ?.takeIf { it >= 0 }\n                    ?: merged.indexOfFirst {\n                        it.originalTitle ==\n                            authoritative.originalTitle &&\n                            it.originalArtist ==\n                                authoritative.originalArtist &&\n                            it.videoId ==\n                                authoritative.videoId\n                    }\n\n            if (targetIndex >= 0) {\n                merged[targetIndex] =\n                    authoritative\n            } else {\n                merged += authoritative\n            }\n        }\n\n        merged.sortBy { it.index }\n\n        val now = System.currentTimeMillis()\n', 'name': 'Overlay authoritative coordinator track states into History'}, {'file': 'app/src/main/java/com/saney/ytmimporter/MainActivity.kt', 'old': '                writeTargetCount =\n                    existing?.writeTargetCount\n                        ?: job.totalCount,\n                addedCount =\n                    merged.count {\n                        it.status == TrackStatus.ADDED.name\n                    },\n                failedCount =\n                    merged.count {\n                        it.status == TrackStatus.FAILED.name\n                    },\n', 'new': '                writeTargetCount =\n                    job.totalCount,\n                addedCount =\n                    job.addedCount,\n                failedCount =\n                    job.failedCount,\n', 'name': 'Use PendingJob write counters as History authority'}, {'file': 'app/src/main/java/com/saney/ytmimporter/model/HistoryResultSemantics.kt', 'old': '                label = "Додано в YTM",\n                value =\n                    "${entry.addedCount}/${entry.writeTargetCount}"\n            )\n', 'new': '                label = "Додано в YTM",\n                value =\n                    "${effectiveRemoteAddedCount(entry)}/${entry.writeTargetCount}"\n            )\n', 'name': 'Use effective remote added count'}, {'file': 'app/src/main/java/com/saney/ytmimporter/model/HistoryResultSemantics.kt', 'old': '    private fun hasRemoteWriteEvidence(\n        entry: HistoryEntry\n    ): Boolean =\n', 'new': '    private fun effectiveRemoteAddedCount(\n        entry: HistoryEntry\n    ): Int {\n        val safeLegacyNewPlaylistRecovery =\n            entry.destination ==\n                PendingDestination.NEW_PLAYLIST &&\n                entry.status ==\n                    HistoryStatus.COMPLETED &&\n                entry.addedCount == 0 &&\n                entry.writeTargetCount > 0 &&\n                entry.failedCount == 0 &&\n                entry.pendingCount == 0\n\n        return if (\n            safeLegacyNewPlaylistRecovery\n        ) {\n            entry.writeTargetCount\n        } else {\n            entry.addedCount\n        }\n    }\n\n    private fun hasRemoteWriteEvidence(\n        entry: HistoryEntry\n    ): Boolean =\n', 'name': 'Safely repair legacy completed new-playlist 0/N display'}, {'file': 'scripts/release-preflight.sh', 'old': 'check_file "scripts/v1447-r3-history-lifecycle-polish-r9-audit.sh"\n\nbash scripts/mainactivity-audit.sh\n', 'new': 'check_file "scripts/v1447-r3-history-lifecycle-polish-r9-audit.sh"\ncheck_file "scripts/v1447-r3-history-counters-r9-fix5-audit.sh"\n\nbash scripts/mainactivity-audit.sh\n', 'name': 'Register R9 FIX5 audit'}, {'file': 'scripts/release-preflight.sh', 'old': 'bash scripts/v1447-r3-history-lifecycle-polish-r9-audit.sh\nbash scripts/project-handoff-audit.sh\n', 'new': 'bash scripts/v1447-r3-history-lifecycle-polish-r9-audit.sh\nbash scripts/v1447-r3-history-counters-r9-fix5-audit.sh\nbash scripts/project-handoff-audit.sh\n', 'name': 'Run R9 FIX5 audit'}, {'file': 'docs/v.1.4.47/qa/BUG_REGISTER.md', 'old': 'Status: **R9 FIX PREPARED — PHONE RETEST NEEDED**.\n\n### BUG-004 R3 hardening\n', 'new': "Status: **R9 FIX PREPARED — PHONE RETEST NEEDED**.\n\n### BUG-026 — completed YTM write can show `Додано в YTM 0/N`\n\nPhone evidence:\n- completed new-playlist write displayed `Додано в YTM 0/28`;\n- the operation was completed and the playlist has a remote YTM id;\n- the History denominator was present, but its numerator was derived from a stale\n  `playlist?.tracks` snapshot instead of the coordinator's authoritative `PendingJob`.\n\nRoot cause:\n- R8 already made write-progress UI use the coordinator's `tracks` as\n  `stateSourceTracks`;\n- History still reconstructed `addedCount` / `failedCount` by counting status values\n  from the display/workspace track list;\n- on paths where the write subset and workspace list are different object graphs,\n  History can therefore remain at zero even while `PendingJob.addedCount` is correct.\n\nR9 FIX5 target:\n- pass the coordinator write subset into `syncHistoryFromJob`;\n- overlay those states into History track details;\n- use `PendingJob.addedCount`, `PendingJob.failedCount`, and `PendingJob.totalCount`\n  as the authoritative remote-write counters;\n- for already-stored legacy `COMPLETED + NEW_PLAYLIST + 0/N` entries with no\n  failure/pending evidence, render `N/N` without rewriting stored JSON;\n- existing-playlist duplicate cases are not guessed by this legacy fallback.\n\nStatus: **R9 FIX5 PREPARED — PHONE RETEST NEEDED**.\n\n### BUG-004 R3 hardening\n", 'name': 'Record BUG-026 History write-counter defect'}]
NEW_FILES = {'docs/v.1.4.47/qa/R3_HISTORY_COUNTERS_R9_FIX5.md': '# v1.4.47-R3 — History Counters R9 FIX5\n\nBase working tree:\n- R9 + FIX2 + FIX3 + FIX4 applied;\n- full release preflight passed;\n- no commit / no push yet.\n\n## Phone finding\n\nA completed new-playlist History record showed:\n\n`Додано в YTM 0/28`\n\neven though the YTM write completed.\n\n## Root cause\n\n`PlaylistWriteCoordinator` already owns authoritative write counters in `PendingJob`:\n- `addedCount`;\n- `failedCount`;\n- `totalCount`.\n\nR8 also established that the coordinator write subset can be a different object graph\nfrom the workspace/display list.\n\nHistory had not adopted that rule. `MainActivity.syncHistoryFromJob()` still counted\n`ADDED` / `FAILED` states from `playlist?.tracks`, so the stored History numerator\ncould stay zero while `PendingJob.addedCount` was correct.\n\n## FIX5 contract\n\nFor new History writes:\n- `writeTargetCount = job.totalCount`;\n- `addedCount = job.addedCount`;\n- `failedCount = job.failedCount`;\n- coordinator `stateSourceTracks` are overlaid into History track details;\n- duplicate/skipped/missing detail remains derived from the merged full track view.\n\nFor legacy stored entries:\n- only a completed `NEW_PLAYLIST` remote write with `0/N`, `N > 0`,\n  zero failed and zero pending may display `N/N`;\n- existing-playlist entries are never inferred by that compatibility fallback;\n- stored History JSON is not rewritten.\n\nPhone QA remains authoritative.\n', 'scripts/v1447-r3-history-counters-r9-fix5-audit.sh': '#!/usr/bin/env bash\nset -euo pipefail\nfail(){ echo "FAIL: $1" >&2; exit 1; }\n\nMAIN="app/src/main/java/com/saney/ytmimporter/MainActivity.kt"\nSEM="app/src/main/java/com/saney/ytmimporter/model/HistoryResultSemantics.kt"\nDOC="docs/v.1.4.47/qa/R3_HISTORY_COUNTERS_R9_FIX5.md"\nBUGS="docs/v.1.4.47/qa/BUG_REGISTER.md"\n\nfor f in "$MAIN" "$SEM" "$DOC" "$BUGS"; do\n  test -f "$f" || fail "missing R9 FIX5 file: $f"\ndone\n\npython - "$MAIN" "$SEM" "$DOC" "$BUGS" <<\'PY\'\nfrom pathlib import Path\nimport sys\n\nmain, sem, doc, bugs = [\n    Path(p).read_text(encoding="utf-8")\n    for p in sys.argv[1:]\n]\n\nfor n in [\n    "stateSourceTracks = tracks",\n    "stateSourceTracks: List<Track>",\n    "stateSourceTracks.forEachIndexed",\n    "writeTargetCount =\\n                    job.totalCount",\n    "addedCount =\\n                    job.addedCount",\n    "failedCount =\\n                    job.failedCount",\n]:\n    if n not in main:\n        raise SystemExit(f"FAIL: History counter authority missing: {n}")\n\nsync0 = main.index("private fun syncHistoryFromJob(")\nsync1 = main.index("private fun historyTrackFromTrack(", sync0)\nsync = main[sync0:sync1]\n\nif "merged.count {\\n                        it.status == TrackStatus.ADDED.name" in sync:\n    raise SystemExit("FAIL: History still derives addedCount from merged display state")\n\nif "merged.count {\\n                        it.status == TrackStatus.FAILED.name" in sync:\n    raise SystemExit("FAIL: History still derives failedCount from merged display state")\n\nfor n in [\n    "private fun effectiveRemoteAddedCount(",\n    "PendingDestination.NEW_PLAYLIST",\n    "HistoryStatus.COMPLETED",\n    "entry.addedCount == 0",\n    "entry.writeTargetCount > 0",\n    "entry.failedCount == 0",\n    "entry.pendingCount == 0",\n    "entry.writeTargetCount",\n]:\n    if n not in sem:\n        raise SystemExit(f"FAIL: legacy 0/N recovery guard missing: {n}")\n\nif \'"${effectiveRemoteAddedCount(entry)}/${entry.writeTargetCount}"\' not in sem:\n    raise SystemExit("FAIL: HistoryResultSemantics does not use effective added count")\n\nfor n in [\n    "BUG-026",\n    "stale",\n    "PendingJob.addedCount",\n]:\n    if n not in bugs:\n        raise SystemExit(f"FAIL: BUG-026 register evidence missing: {n}")\n\nfor n in [\n    "History Counters R9 FIX5",\n    "writeTargetCount = job.totalCount",\n    "existing-playlist entries are never inferred",\n]:\n    if n not in doc:\n        raise SystemExit(f"FAIL: FIX5 doc contract missing: {n}")\n\nprint("PASS:")\nprint("- History write counters come from PendingJob authority")\nprint("- coordinator track subset overlays History track details")\nprint("- legacy completed NEW_PLAYLIST 0/N can render N/N safely")\nprint("- existing-playlist duplicate history is not guessed")\nPY\n'}

def patch(op, apply):
    p = Path(op["file"])
    if not p.exists():
        raise SystemExit(f"FAIL: missing file: {p}")

    text = p.read_text(encoding="utf-8")
    old, new = op["old"], op["new"]
    old_count = text.count(old)
    new_count = text.count(new)

    if old_count == 0 and new_count == 1:
        print(f"SKIP: already applied: {op['name']}")
        return

    if old_count != 1:
        raise SystemExit(
            f"FAIL: FIX5 anchor mismatch for {op['name']}: "
            f"old={old_count}, new={new_count}"
        )

    print(f"READY: {op['name']}")
    if apply:
        p.write_text(
            text.replace(old, new, 1),
            encoding="utf-8",
            newline="\n",
        )
        print(f"APPLIED: {op['name']}")

def ensure(rel, content, apply):
    p = Path(rel)
    if p.exists():
        if p.read_text(encoding="utf-8") == content:
            print(f"SKIP: already present: {rel}")
            return
        raise SystemExit(f"FAIL: generated file differs: {rel}")
    print(f"READY: create {rel}")
    if apply:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding="utf-8", newline="\n")
        print(f"CREATED: {rel}")

check = "--check" in sys.argv[1:]
for op in OPS:
    patch(op, not check)
for rel, content in NEW_FILES.items():
    ensure(rel, content, not check)

print("PASS: R9 FIX5 ready" if check else "PASS: R9 FIX5 applied")
